import { ResourceAllocationOverview } from '../types';
import { hasPublicisChartEntry } from './hasPublicisChartEntry';

export const hasOverviewChartData = (
  chartsData?: ResourceAllocationOverview,
): boolean => {
  if (!chartsData || typeof chartsData !== 'object') {
    return false;
  }

  return Object.values(chartsData).some((entry) => {
    if (hasPublicisChartEntry(entry)) {
      return true;
    }

    if (entry && typeof entry === 'object') {
      return Object.values(entry as ResourceAllocationOverview).some(
        hasPublicisChartEntry,
      );
    }

    return false;
  });
};
